<?php
namespace App\Services;
use App\Models\{Group,Expense,Settlement,User};
class BalanceService {
 public function balances(Group $g):array { $ids=array_map('strval',$g->member_ids??[]); $b=array_fill_keys($ids,0.0); foreach(Expense::where('group_id',(string)$g->_id)->get() as $e){$p=(string)$e->paid_by;$b[$p]=($b[$p]??0)+$e->amount;foreach($e->participants as $part){$id=(string)$part['user_id'];$b[$id]=($b[$id]??0)-((float)$part['amount']);}} foreach(Settlement::where('group_id',(string)$g->_id)->get() as $s){$from=(string)$s->paid_by;$to=(string)$s->paid_to;$b[$from]=($b[$from]??0)+$s->amount;$b[$to]=($b[$to]??0)-$s->amount;} $users=User::whereIn('_id',$ids)->get()->keyBy(fn($u)=>(string)$u->_id); return array_map(fn($id)=>['user_id'=>$id,'name'=>$users[$id]->name??'Unknown','balance'=>round($b[$id]??0,2)],$ids); }
 public function debts(Group $g):array { $balances=$this->balances($g);$credit=[];$debit=[];foreach($balances as $b){$v=round($b['balance'],2);if($v>0.009)$credit[]=['id'=>$b['user_id'],'name'=>$b['name'],'amount'=>$v];elseif($v<-0.009)$debit[]=['id'=>$b['user_id'],'name'=>$b['name'],'amount'=>-$v];}$out=[];$i=0;$j=0;while($i<count($debit)&&$j<count($credit)){ $amt=min($debit[$i]['amount'],$credit[$j]['amount']);$out[]=['from_user_id'=>$debit[$i]['id'],'from_name'=>$debit[$i]['name'],'to_user_id'=>$credit[$j]['id'],'to_name'=>$credit[$j]['name'],'amount'=>round($amt,2)];$debit[$i]['amount']=round($debit[$i]['amount']-$amt,2);$credit[$j]['amount']=round($credit[$j]['amount']-$amt,2);if($debit[$i]['amount']<=0.009)$i++;if($credit[$j]['amount']<=0.009)$j++;}return $out; }
}
